/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, './migrations/');

// Read and sort migration files
const readMigrationFiles = () => {
  try {
    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log('No migrations directory found. Skipping.');
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter out non-SQL files and sort them by filename
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (err) {
    console.error('Error reading migration files:', err);
    return [];
  }
};

// Log each migration file in order
const logMigrations = () => {
  const migrationFiles = readMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
};

// Run the migration logging
logMigrations();

