#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory where migration files are stored
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function getSortedMigrationFiles() {
  try {
    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter out non-SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Extract the numeric prefix (e.g., "001_create_table.sql")
        const aNum = parseInt(a.split('_')[0], 10);
        const bNum = parseInt(b.split('_')[0], 10);
        return aNum - bNum;
      });

    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }
}

// Main function to log migration files
function logMigrations() {
  console.log('Migration files to be applied in order:');
  const migrationFiles = getSortedMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Run the script
logMigrations();

