  console.log(`Audit service response status: ${res.statusCode}`);
  res.on('data', (chunk) => {
    console.log(`Audit service response: ${chunk}`);
  });
});

req.on('error', (error) => {
  console.error('Error sending audit data:', error);
});

req.write(postData);
req.end();

