const fs = require('fs');
const path = require('path');

// Manually load environment variables from .env.test
const dotenvPath = path.resolve(__dirname, '.env.test');
const envConfig = fs.readFileSync(dotenvPath, 'utf8');
const envLines = envConfig.split('\n');

const envVars = {};
envLines.forEach(line => {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key, value] = trimmedLine.split('=');
        if (key && value) {
            envVars[key] = value;
        }
    }
});

// Set environment variables
process.env.DATABASE_URL = envVars.DATABASE_URL;

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Read DATABASE_URL from environment variables
const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
    console.error('Error: DATABASE_URL is not set in .env.test.');
